597	   373	      return;
598	   374	    }
599	   375	    if (from !== '' && to !== '' && to < from) {
600	   376	      this.setError(pool.id, 'A to-date is not before the from-date.');
601	   377	      return;
602	   378	    }
603	   379	    this.busy = true;
