606	   382	      this.pools.update((all) => all.map((p) => (p.id === saved.id ? saved : p)));
607	   383	      this.drafts.update((all) => {
608	   384	        const next = new Map(all);
609	   385	        next.delete(pool.id);
610	   386	        return next;
611	   387	      });
612	   388	    } catch {
613	   389	      this.setError(pool.id, 'The member could not be added: they may already be in the pool, or the pool in another.');
614	   390	    } finally {
