626	   402	      if (up === memberId) return 'A pool cannot contain itself.';
627	   403	    }
628	   404	    if (parents.has(memberId)) return 'That pool is already a member of a pool.';
629	   405	    let depth = 1;
630	   406	    for (let up = parents.get(poolId); up !== undefined; up = parents.get(up)) depth++;
631	   407	    const height = (id: number): number =>
632	   408	      1 + Math.max(0, ...[...parents].filter(([, parent]) => parent === id).map(([child]) => height(child)));
633	   409	    if (depth + height(memberId) > MAX_DEPTH) return 'A chain of pools is at most three deep.';
634	   410	    return null;
635	   411	  }
