638	   414	    if (message === null && !this.errors().has(poolId)) return;
639	   415	    this.errors.update((all) => {
640	   416	      const next = new Map(all);
641	   417	      if (message === null) next.delete(poolId);
642	   418	      else next.set(poolId, message);
643	   419	      return next;
644	   420	    });
645	   421	  }
