631	      // The refused dates are cleared, so they are not carried into the next rate set.
632	      this.from.set('');
633	      this.to.set('');
634	      this.error.set(`A to-date cannot be before the from-date; ${from} and ${to} were cleared.`);
635	      return;
636	    }
637	    this.busy = true;
638	    try {
639	      this.saved.emit(await this.api.set(sheet, this.grade(), { pct, from: from || null, to: to || null }));
640	      this.pct.set('');
641	      this.from.set('');
642	      this.to.set('');
643	    } catch {
644	      this.error.set(`The rate for grade ${this.grade()} could not be set.`);
645	    } finally {
646	      this.busy = false;
647	    }
648	  }
649	}

